def solve(n: int, s: int, t: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)

    # Apply the oracle for 0 <= k < 2^n
    for i in range(n):
        if s & (1 << i):
            qc.cx(i, n)

    # Apply the oracle for 2^n <= k < t
    for i in range(n):
        if t & (1 << i):
            qc.cx(i, n)
            qc.cz(i, n)

    return qc

