def solve(a: int, L: int) -> int:
    result = 0
    # Extended Euclidean Algorithm
    def extended_gcd(a: int, b: int) -> tuple:
        if b == 0:
            return a, 1, 0
        else:
            gcd, x, y = extended_gcd(b, a % b)
            return gcd, y, x - (a // b) * y

    gcd, x, y = extended_gcd(a, L)
    # If gcd is not 1, then a and L are not coprime
    if gcd!= 1:
        return None

    # The inverse of a modulo L is x modulo L
    result = x % L
    return result

