def solve(n: int) -> QuantumCircuit:
    m, k = QuantumRegister(1), QuantumRegister(n)
    qc = QuantumCircuit(m, k)

    if n == 1:
        qc.cx(m, k)
        qc.z(m)
    else:
        for i in range(n):
            qc.cx(m, k[i])
            qc.cz(k[i], k[i + 1])

    return qc

